from pathlib import Path

ROOT = Path(__file__).resolve().parent

# Run from the repository root, or pass OTC_BOT_ROOT=/path/to/repo.
import os
ROOT=Path(os.environ.get('OTC_BOT_ROOT', ROOT))

SCHEMA=ROOT/'src/models/schemas.py'
ADAPTER=ROOT/'src/api/botv2_adapter.py'
STORAGE=ROOT/'src/data/storage.py'
HANDLERS=ROOT/'src/bot/handlers.py'
MAIN=ROOT/'src/bot/main.py'


def replace_once(path, old, new):
    s=path.read_text(encoding='utf-8-sig')
    if old not in s:
        raise SystemExit(f'Expected source block not found in {path}')
    path.write_text(s.replace(old,new,1), encoding='utf-8')

# 1) Add auditable settlement fields.
replace_once(SCHEMA,
'''    result = Column(String(10), default="PENDING")  # PENDING | WIN | LOSS | DRAW | UNKNOWN\n    payout = Column(Float, nullable=True)\n    closed_at = Column(DateTime, nullable=True)\n''',
'''    result = Column(String(24), default="PENDING")  # PENDING | SETTLING | WIN | LOSS | DRAW | UNKNOWN | REQUIRES_RECONCILIATION\n    payout = Column(Float, nullable=True)\n    profit_loss = Column(Float, nullable=True)\n    broker_result = Column(String(100), nullable=True)\n    settlement_source = Column(String(50), nullable=True)\n    settlement_attempts = Column(Integer, default=0)\n    last_settlement_at = Column(DateTime, nullable=True)\n    closed_at = Column(DateTime, nullable=True)\n''')

# 2) Replace broker check_win with normalized settlement handling.
old='''    async def check_win(self, trade_id: str, timeout: Optional[int] = None) -> dict:\n        if not self.is_connected or self._client is None:\n            raise RuntimeError("BotV2Client is not connected")\n        client = self._client\n        if not hasattr(client, "check_win"):\n            raise AttributeError("Underlying client has no check_win")\n        res = client.check_win(trade_id)\n        if asyncio.iscoroutine(res):\n            res = await asyncio.wait_for(res, timeout=(timeout or 120))\n        if isinstance(res, dict):\n            return res\n        return {"result": res}\n'''
new='''    @staticmethod\n    def _normalize_settlement(res: Any) -> dict:\n        """Normalize broker settlement payloads without guessing.\n\n        Only explicit broker evidence is allowed to become WIN/LOSS/DRAW.\n        Numeric profit is treated as authoritative only when its meaning is\n        explicit; otherwise the trade remains unresolved.\n        """\n        payload = res if isinstance(res, dict) else {"result": res}\n        candidates = [\n            payload.get("result"), payload.get("outcome"), payload.get("status"),\n            payload.get("trade_result"), payload.get("trade_outcome"),\n        ]\n        for value in candidates:\n            if isinstance(value, bool):\n                continue\n            text = str(value or "").strip().upper()\n            compact = text.replace("_", " ").replace("-", " ")\n            if compact in {"WIN", "WON", "PROFIT", "SUCCESS", "ITM"}:\n                return {"result": "WIN", "raw_result": value, "raw": payload}\n            if compact in {"LOSS", "LOST", "LOSE", "FAILED", "FAIL", "OTM"}:\n                return {"result": "LOSS", "raw_result": value, "raw": payload}\n            if compact in {"DRAW", "TIE", "REFUND", "PUSH", "RETURN"}:\n                return {"result": "DRAW", "raw_result": value, "raw": payload}\n\n        # Some broker clients expose a boolean win flag.\n        for key in ("win", "is_win", "won"):\n            if key in payload and isinstance(payload[key], bool):\n                return {"result": "WIN" if payload[key] else "LOSS", "raw_result": payload[key], "raw": payload}\n\n        profit = payload.get("profit", payload.get("net_profit"))\n        if isinstance(profit, (int, float)) and profit != 0:\n            return {"result": "WIN" if float(profit) > 0 else "LOSS", "profit": float(profit), "raw": payload}\n\n        return {"result": "UNKNOWN", "raw": payload}\n\n    async def check_win(self, trade_id: str, timeout: Optional[int] = None) -> dict:\n        if not self.is_connected or self._client is None:\n            raise RuntimeError("BotV2Client is not connected")\n        client = self._client\n        if not hasattr(client, "check_win"):\n            raise AttributeError("Underlying client has no check_win")\n        res = client.check_win(trade_id)\n        if asyncio.iscoroutine(res):\n            res = await asyncio.wait_for(res, timeout=(timeout or 120))\n        normalized = self._normalize_settlement(res)\n        if isinstance(res, dict):\n            normalized.update({k: v for k, v in res.items() if k not in normalized})\n        return normalized\n'''
replace_once(ADAPTER, old, new)

# Expose both canonical names from placement.
replace_once(ADAPTER,
'''            "trade_id": str(trade_id) if trade_id is not None else None,\n            "deal": deal,\n''',
'''            "trade_id": str(trade_id) if trade_id is not None else None,\n            "order_id": str(trade_id) if trade_id is not None else None,\n            "deal": deal,\n''')

# 3) Replace resolver. This is the core correctness fix.
s=STORAGE.read_text(encoding='utf-8-sig')
start=s.index('    async def resolve_pending_trades(')
end=s.index('\n    def get_trade_stats(', start)
new_resolver='''    async def resolve_pending_trades(self, api_client: Any, data_fetcher: Any = None, grace_seconds: int = 5) -> List[Dict[str, Any]]:\n        """Resolve due trades using broker settlement only.\n\n        IMPORTANT: local candles are diagnostic data, never an automatic\n        substitute for broker settlement. Unresolved trades stay open so a\n        transient broker/API response cannot turn a real loss into a win (or\n        vice versa). Final results are idempotent.\n        """\n        now = datetime.utcnow()\n        session = self.db.get_session()\n        just_closed: List[Dict[str, Any]] = []\n        terminal = ("WIN", "LOSS", "DRAW")\n        try:\n            due = (\n                session.query(TradeHistory)\n                .filter(TradeHistory.result.in_(("PENDING", "SETTLING", "UNKNOWN")))\n                .filter(TradeHistory.expiry_at != None)\n                .filter(TradeHistory.expiry_at <= now)\n                .limit(200).all()\n            )\n            for row in due:\n                if row.expiry_at and (now-row.expiry_at).total_seconds() < grace_seconds:\n                    continue\n                row.settlement_attempts = int(row.settlement_attempts or 0) + 1\n                row.last_settlement_at = now\n                row.result = "SETTLING"\n                try:\n                    if not row.order_id or not hasattr(api_client, "check_win"):\n                        row.result = "REQUIRES_RECONCILIATION"\n                        continue\n\n                    res = await api_client.check_win(row.order_id, timeout=20)\n                    broker_result = str(res.get("result") or "UNKNOWN").upper()\n                    row.broker_result = str(res.get("raw_result") or broker_result)[:100]\n\n                    if broker_result not in terminal:\n                        row.result = "PENDING"\n                        continue\n\n                    # Never overwrite an already terminal result with a conflicting result.\n                    if row.result in terminal and row.result != broker_result:\n                        logger.error("Settlement conflict for trade %s: existing=%s broker=%s", row.id, row.result, broker_result)\n                        row.result = "REQUIRES_RECONCILIATION"\n                        continue\n\n                    row.result = broker_result\n                    row.settlement_source = "broker_check_win"\n                    if res.get("profit") is not None:\n                        row.profit_loss = float(res["profit"])\n                    elif res.get("payout") is not None:\n                        row.payout = float(res["payout"])\n                        row.profit_loss = row.payout - float(row.amount or 0)\n                    row.closed_at = now\n                    just_closed.append({\n                        "id": row.id, "telegram_id": row.telegram_id, "chat_id": row.chat_id,\n                        "asset": row.asset, "direction": row.direction, "amount": row.amount,\n                        "result": row.result, "order_id": row.order_id,\n                        "profit_loss": row.profit_loss,\n                    })\n                except Exception:\n                    logger.exception("Failed to resolve trade id=%s order=%s", row.id, row.order_id)\n                    row.result = "PENDING"\n            session.commit()\n        finally:\n            session.close()\n        return just_closed\n'''
s=s[:start]+new_resolver+s[end:]
STORAGE.write_text(s,encoding='utf-8')

# 4) Add period reporting methods before get_trade_stats.
insert='''\n    def get_trade_report(self, start_at: datetime, end_at: datetime, user_id: Optional[int] = None) -> Dict[str, Any]:\n        """Comprehensive executed-trade report for a half-open UTC period."""\n        session=self.db.get_session()\n        try:\n            q=session.query(TradeHistory).filter(TradeHistory.placed_at>=start_at, TradeHistory.placed_at<end_at)\n            if user_id is not None:\n                user=session.query(User).filter_by(telegram_id=str(user_id)).first()\n                if user is None: return {"total":0,"settled":0,"wins":0,"losses":0,"draws":0,"pending":0,"unresolved":0,"win_rate":0.0,"stake":0.0,"payout":0.0,"net_pl":0.0,"trades":[]}\n                q=q.filter(TradeHistory.user_id==user.id)\n            rows=q.order_by(TradeHistory.placed_at.asc()).all()\n            wins=sum(r.result=="WIN" for r in rows); losses=sum(r.result=="LOSS" for r in rows); draws=sum(r.result=="DRAW" for r in rows)\n            settled=wins+losses+draws; stake=sum(float(r.amount or 0) for r in rows)\n            payout=sum(float(r.payout or 0) for r in rows)\n            net=sum(float(r.profit_loss or 0) for r in rows)\n            if not net:\n                net=sum((float(r.payout or 0)-float(r.amount or 0)) for r in rows if r.result in ("WIN","LOSS","DRAW") and r.payout is not None)\n            return {\n                "total":len(rows), "settled":settled, "wins":wins, "losses":losses, "draws":draws,\n                "pending":sum(r.result in ("PENDING","SETTLING") for r in rows),\n                "unresolved":sum(r.result in ("UNKNOWN","REQUIRES_RECONCILIATION") for r in rows),\n                "win_rate":round(100*wins/(wins+losses),2) if wins+losses else 0.0,\n                "stake":round(stake,2), "payout":round(payout,2), "net_pl":round(net,2),\n                "call":{"total":sum(r.direction.upper()=="CALL" for r in rows),"wins":sum(r.direction.upper()=="CALL" and r.result=="WIN" for r in rows)},\n                "put":{"total":sum(r.direction.upper()=="PUT" for r in rows),"wins":sum(r.direction.upper()=="PUT" and r.result=="WIN" for r in rows)},\n                "by_asset":self._aggregate_by_asset(rows),\n                "trades":[{"id":r.id,"asset":r.asset,"direction":r.direction,"amount":r.amount,"result":r.result,"profit_loss":r.profit_loss,"placed_at":r.placed_at.isoformat() if r.placed_at else None,"closed_at":r.closed_at.isoformat() if r.closed_at else None,"order_id":r.order_id} for r in rows]\n            }\n        finally: session.close()\n\n    @staticmethod\n    def _aggregate_by_asset(rows):\n        out={}\n        for r in rows:\n            a=r.asset or "UNKNOWN"; d=out.setdefault(a,{"total":0,"wins":0,"losses":0,"draws":0,"stake":0.0,"net_pl":0.0})\n            d["total"]+=1; d["wins"]+=r.result=="WIN"; d["losses"]+=r.result=="LOSS"; d["draws"]+=r.result=="DRAW"; d["stake"]+=float(r.amount or 0); d["net_pl"]+=float(r.profit_loss or 0)\n        return out\n\n'''
idx=STORAGE.index if False else s.index('    def get_trade_stats(')
s=STORAGE.read_text(encoding='utf-8')
s=s[:s.index('    def get_trade_stats(')]+insert+s[s.index('    def get_trade_stats('):]
STORAGE.write_text(s,encoding='utf-8')

# 5) Add daily/weekly/monthly commands using Africa/Lagos boundaries, without changing existing premium gate.
handlers=HANDLERS.read_text(encoding='utf-8-sig')
handlers=handlers.replace('from datetime import datetime, timezone, timedelta','from datetime import datetime, timezone, timedelta\nfrom zoneinfo import ZoneInfo')
marker='\n\nasync def analytics_inline_callback'
report_code='''\n\ndef _period_bounds(kind: str):\n    tz=ZoneInfo("Africa/Lagos"); now=datetime.now(tz)\n    if kind=="daily": start=now.replace(hour=0,minute=0,second=0,microsecond=0); label="Today"\n    elif kind=="weekly":\n        start=(now-timedelta(days=now.weekday())).replace(hour=0,minute=0,second=0,microsecond=0); label="This Week"\n    else:\n        start=now.replace(day=1,hour=0,minute=0,second=0,microsecond=0); label="This Month"\n    end=now\n    return start.astimezone(timezone.utc).replace(tzinfo=None), end.astimezone(timezone.utc).replace(tzinfo=None), label\n\nasync def _period_report(update, context, kind):\n    user=update.effective_user\n    if user is None: return\n    storage=context.bot_data.get("storage") or DataStorage()\n    start,end,label=_period_bounds(kind)\n    r=storage.get_trade_report(start,end,user_id=user.id)\n    lines=[f"📊 <b>{label} Trading Report</b>","",f"Trades: <b>{r['total']}</b>",f"Settled: <b>{r['settled']}</b>",f"Wins: <b>{r['wins']}</b> | Losses: <b>{r['losses']}</b> | Draws: <b>{r['draws']}</b>",f"Win rate: <b>{r['win_rate']:.2f}%</b>",f"Pending: <b>{r['pending']}</b> | Unresolved: <b>{r['unresolved']}</b>","",f"Stake: <b>{r['stake']:.2f}</b>",f"Payout: <b>{r['payout']:.2f}</b>",f"Net P/L: <b>{r['net_pl']:.2f}</b>","",f"CALL: {r['call']['wins']}/{r['call']['total']} wins",f"PUT: {r['put']['wins']}/{r['put']['total']} wins"]\n    if r['by_asset']:\n        lines += ["","<b>By asset</b>"]+[f"• {a}: {v['wins']}W/{v['losses']}L | P/L {v['net_pl']:.2f}" for a,v in sorted(r['by_asset'].items())]\n    if kind=="weekly": lines += ["","<i>Week: Monday 00:00 through Sunday/current time, Africa/Lagos.</i>"]\n    await (update.message.reply_text if update.message else update.callback_query.edit_message_text)("\\n".join(lines),parse_mode="HTML")\n\nasync def daily_report_command(update, context): await _period_report(update,context,"daily")\nasync def weekly_report_command(update, context): await _period_report(update,context,"weekly")\nasync def monthly_report_command(update, context): await _period_report(update,context,"monthly")\n'''
handlers=handlers.replace(marker,report_code+marker,1)
HANDLERS.write_text(handlers,encoding='utf-8')

# 6) Register commands.
main=MAIN.read_text(encoding='utf-8-sig')
main=main.replace('    analytics_inline_callback,','    analytics_inline_callback,\n    daily_report_command,\n    weekly_report_command,\n    monthly_report_command,')
main=main.replace('        self.application.add_handler(CommandHandler("analytics", analytics_command))','        self.application.add_handler(CommandHandler("analytics", analytics_command))\n        self.application.add_handler(CommandHandler("daily", daily_report_command))\n        self.application.add_handler(CommandHandler("weekly", weekly_report_command))\n        self.application.add_handler(CommandHandler("monthly", monthly_report_command))')
MAIN.write_text(main,encoding='utf-8')

print('Applied settlement/reporting patch to', ROOT)
